import{_ as e,a,o,a2 as r}from"./chunks/framework.DCcmcJcL.js";const g=JSON.parse('{"title":"Generative AI (Magic AI)","description":"","frontmatter":{},"headers":[],"relativePath":"generative-ai/introduction.md","filePath":"generative-ai/introduction.md","lastUpdated":1789331284000}'),i={name:"generative-ai/introduction.md"};function n(s,t,d,h,c,l){return o(),a("div",null,t[0]||(t[0]=[r('<h1 id="generative-ai-magic-ai" tabindex="-1">Generative AI (Magic AI) <a class="header-anchor" href="#generative-ai-magic-ai" aria-label="Permalink to &quot;Generative AI (Magic AI)&quot;">​</a></h1><p>Bagisto has generative AI built into the platform. Branded <strong>Magic AI</strong> in the admin, it uses the text and image models of the AI provider you choose to write, draw, translate and describe, so the content work behind a store takes minutes rather than hours. It is part of Bagisto itself; there is nothing extra to install.</p><h2 id="what-you-can-do-with-it" tabindex="-1">What you can do with it <a class="header-anchor" href="#what-you-can-do-with-it" aria-label="Permalink to &quot;What you can do with it&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Who uses it</th><th>What it does</th></tr></thead><tbody><tr><td><a href="./generate-content.html">Generate text content</a></td><td>Admin</td><td>Writes or rewrites product and category descriptions, CMS pages and email templates from a prompt, in any rich-text editor.</td></tr><tr><td><a href="./generate-images.html">Generate product images</a></td><td>Admin</td><td>Creates product images from a written description, in the size and quality you pick.</td></tr><tr><td><a href="./image-search.html">AI image search</a></td><td>Shopper</td><td>Understands the photo a shopper uploads in the search bar and finds matching products.</td></tr><tr><td><a href="./review-translation.html">Review translation</a></td><td>Shopper</td><td>Shows a product review in the shopper&#39;s language with one click.</td></tr><tr><td><a href="./checkout-message.html">Personalized checkout message</a></td><td>Shopper</td><td>Writes a short thank-you for the order confirmation page that mentions what was bought.</td></tr></tbody></table><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ul><li><strong>Your provider, your model.</strong> Bagisto connects to <strong>OpenAI, Anthropic, Gemini, Groq, xAI, DeepSeek, Mistral</strong> and <strong>Ollama</strong>. You add the API key of the providers you use, and you choose the model per feature. Ollama runs open models on your own server, so nothing leaves it.</li><li><strong>Admin features suggest, you decide.</strong> Generated text and images are shown in a dialog first and go into the product, page or template only when you click <strong>Apply</strong>.</li><li><strong>Storefront features respond to the shopper.</strong> A photo is analysed when the shopper searches with it, a review is translated when they click <strong>Translate</strong>, and the checkout message is written when the order is placed. Each of these is switched on per channel with its own model.</li></ul><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>Everything is configured under <strong>Configure &gt;&gt; Magic AI</strong>. Follow <a href="./../configure/magic-ai.html">Generative AI Configuration</a> to turn the feature on, connect a provider and enable the features you want, then come back to the feature pages above.</p><h2 id="what-it-does-not-do" tabindex="-1">What it does not do <a class="header-anchor" href="#what-it-does-not-do" aria-label="Permalink to &quot;What it does not do&quot;">​</a></h2><p>Magic AI does not run the store by itself. It does not publish content, change prices, place orders or answer customers. Everything it produces in the admin is reviewed and applied by you, and on the storefront it only reacts to what the shopper does. Text and images from an AI model can be wrong or misleading, which is why the admin dialogs ask you to review the result before applying it.</p>',10)]))}const p=e(i,[["render",n]]);export{g as __pageData,p as default};
